import java.util.*;
import java.util.stream.Collectors;

public class SimpleInvertedIndex {
    private final Map<String, List<Integer>> index = new HashMap<>();

    public void addDocument(int docId, String text) {
        String[] tokens = text.toLowerCase().replaceAll("[^a-zA-Z0-9\\s]", "").split("\\s+");
        Set<String> uniqueTokens = new HashSet<>(Arrays.asList(tokens));

        for (String token : uniqueTokens) {
            index.computeIfAbsent(token, k -> new ArrayList<>()).add(docId);
        }
    }

    public List<Integer> search(String query) {
        String cleanQuery = query.toLowerCase().trim();
        return index.getOrDefault(cleanQuery, Collections.emptyList());
    }

    public static void main(String[] args) {
        SimpleInvertedIndex searchEngine = new SimpleInvertedIndex();
        searchEngine.addDocument(1, "Java is a high-performance programming language.");
        searchEngine.addDocument(2, "Garbage collection in the JVM manages memory.");
        searchEngine.addDocument(3, "Java and JVM internals are fascinating.");

        System.out.println("Search 'java': " + searchEngine.search("java"));
    }
}
